package com.aoo.bcg.gifting;
import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.*;import java.io.IOException;import java.util.*;
public final class GiftingHttpRoutes {
 private final GiftingService service;private final GiftingRequestAuthenticator auth;private final ObjectMapper json;public GiftingHttpRoutes(GiftingService s,GiftingRequestAuthenticator a,ObjectMapper j){service=s;auth=a;json=j;}public GiftingHttpRoutes(GiftingService s,PlayerAuthenticator a,ObjectMapper j){this(s,(authorization,device,channel,version,ip)->a.authenticate(authorization),j);}
 public void mount(HttpServer server){server.createContext("/health/gifting",e->reply(e,200,Map.of("status","UP","persistence","jdbc","authorities",List.of("billing","inventory"))));server.createContext("/v1/gifts",this::handle);}
 private void handle(HttpExchange e)throws IOException{try{if(!"1".equals(e.getRequestHeaders().getFirst("X-API-Version")))throw new Api(426,"API_VERSION_REQUIRED","X-API-Version: 1 required");long player=auth.authenticate(e.getRequestHeaders().getFirst("Authorization"),header(e,"X-Device-Id"),header(e,"X-Client-Channel"),header(e,"X-Client-Version"),e.getRemoteAddress().getAddress().getHostAddress());String path=e.getRequestURI().getPath();Object data;if("POST".equals(e.getRequestMethod())&&path.equals("/v1/gifts")){Map<String,Object>b=body(e);data=service.gift(key(e),player,num(b,"recipientId"),text(b,"asset"),num(b,"quantity"),header(e,"X-Device-Id"),e.getRemoteAddress().getAddress().getHostAddress());}else if("GET".equals(e.getRequestMethod())&&path.equals("/v1/gifts/ledger")){data=service.ledger(player,50);}else if("GET".equals(e.getRequestMethod())&&path.equals("/v1/gifts/inbox")){data=service.inbox(player,queryLong(e,"after",0));}else if("GET".equals(e.getRequestMethod())&&path.startsWith("/v1/gifts/")){data=service.status(path.substring(10),player);}else throw new Api(405,"METHOD_NOT_ALLOWED","unsupported gifting operation");reply(e,200,Map.of("code","OK","data",data));}catch(Api x){reply(e,x.status,Map.of("code",x.code,"message",x.getMessage()));}catch(JdbcGiftRepository.GiftError x){reply(e,409,Map.of("code",x.code,"message",x.getMessage()));}catch(SecurityException x){reply(e,401,Map.of("code","UNAUTHORIZED","message",x.getMessage()));}catch(IllegalArgumentException x){reply(e,400,Map.of("code","INVALID_REQUEST","message",x.getMessage()));}catch(Exception x){reply(e,503,Map.of("code","GIFT_DEPENDENCY_UNAVAILABLE","message","gift could not be completed; compensation scheduled"));}}
 @SuppressWarnings("unchecked")private Map<String,Object>body(HttpExchange e)throws IOException{return json.readValue(e.getRequestBody(),Map.class);}private static long queryLong(HttpExchange e,String name,long fallback){String raw=e.getRequestURI().getRawQuery();if(raw==null)return fallback;for(String pair:raw.split("&")){String[]parts=pair.split("=",2);if(parts.length==2&&parts[0].equals(name)){long value=Long.parseLong(parts[1]);if(value<0)throw new IllegalArgumentException(name+" invalid");return value;}}return fallback;}private static String key(HttpExchange e){String k=e.getRequestHeaders().getFirst("Idempotency-Key");if(k==null||!k.matches("[A-Za-z0-9_.:-]{1,128}"))throw new IllegalArgumentException("valid Idempotency-Key required");return k;}private static String header(HttpExchange e,String n){String v=e.getRequestHeaders().getFirst(n);if(v==null||v.isBlank()||v.length()>128)throw new IllegalArgumentException(n+" required");return v;}private static String text(Map<String,Object>b,String k){Object v=b.get(k);if(!(v instanceof String s)||!s.matches("[A-Za-z0-9_.:-]{1,64}"))throw new IllegalArgumentException(k+" invalid");return s;}private static long num(Map<String,Object>b,String k){if(b.get(k)instanceof Number n)return n.longValue();throw new IllegalArgumentException(k+" required");}private void reply(HttpExchange e,int s,Object v)throws IOException{byte[]b=json.writeValueAsBytes(v);e.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");e.getResponseHeaders().set("Cache-Control","no-store");e.sendResponseHeaders(s,b.length);try(var o=e.getResponseBody()){o.write(b);}}private static final class Api extends RuntimeException{final int status;final String code;Api(int s,String c,String m){super(m);status=s;code=c;}}
}
